def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    if text.endswith('\n'):
        lines = text[:-1].split('\n')
    else:
        lines = text.split('\n')

    result = {}
    current_section = ""
    last_key = None

    for line_num, line in enumerate(lines, 1):
        # Rule 1: Drop \r before \n
        if line.endswith('\r'):
            line = line[:-1]

        # Rule 2: Skip empty/whitespace-only lines
        if not line.strip():
            continue

        # Rule 2: Skip comments (first non-whitespace is ; or #)
        if line.lstrip()[0] in ';#':
            continue

        # Rule 7: Check for continuation (starts with space or tab)
        if line[0] in ' \t':
            if last_key is None:
                raise ValueError(f"line {line_num}")
            continuation = line.lstrip()
            result[current_section][last_key] += '\n' + continuation
            continue

        # Rule 3: Check for section header
        if line[0] == '[':
            if ']' not in line:
                raise ValueError(f"line {line_num}")
            end_bracket = line.index(']')
            section_name = line[1:end_bracket].strip()
            if not section_name:
                raise ValueError(f"line {line_num}")
            current_section = section_name
            last_key = None
            if current_section not in result:
                result[current_section] = {}
            continue

        # Rule 4, 5: Check for key=value
        if '=' in line:
            key, _, value = line.partition('=')
            key = key.strip().lower()
            value = value.strip()
            if not key:
                raise ValueError(f"line {line_num}")
            if current_section not in result:
                result[current_section] = {}
            result[current_section][key] = value
            last_key = key
            continue

        # Rule 10: Any other line is an error
        raise ValueError(f"line {line_num}")

    # Rule 6: Remove empty "" section if it has no keys
    if "" in result and not result[""]:
        del result[""]

    return result
